"""The ``pennywise`` command."""

import argparse
import csv
import io
import json
import os
import re
import sys
from decimal import Context, Decimal

from . import ledger
from .ledger import ParseError

_CENT = Decimal("0.01")
_VALUE_OPTS = ("--category", "--since", "--until", "--by", "--format")
_KNOWN_FLAGS = _VALUE_OPTS + ("--json", "-h", "--help")


class _Exit(Exception):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message


def money(amount):
    """Two-decimal text for an amount; negative zero prints as 0.00."""
    ctx = Context(prec=max(28, len(amount.as_tuple().digits) + 4))
    q = ctx.quantize(amount, _CENT)
    if q == 0:
        q = Decimal("0.00")
    return format(q, "f")


def entry_line(e):
    line = "%s %s %s" % (e.date.isoformat(), e.category, money(e.amount))
    return line + " " + e.note if e.note else line


def _date_arg(text):
    try:
        return ledger.parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser():
    p = argparse.ArgumentParser(
        prog="pennywise",
        description="Read a plain-text household ledger. FILE '-' reads standard input.",
    )
    sub = p.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def reader(name, help_):
        sp = sub.add_parser(name, help=help_, allow_abbrev=False)
        sp.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
        return sp

    sp = reader("balance", "print the total")
    sp.add_argument("--json", action="store_true", help="print JSON")
    sp = reader("summary", "totals per category or month")
    sp.add_argument("--by", choices=("category", "month"), default="category")
    sp.add_argument("--json", action="store_true", help="print JSON")
    sp = reader("list", "list entries, oldest first")
    sp.add_argument("--category", metavar="C")
    sp.add_argument("--since", metavar="DATE", type=_date_arg)
    sp.add_argument("--until", metavar="DATE", type=_date_arg)
    sp.add_argument("--json", action="store_true", help="print JSON")
    sp = reader("export", "print entries as CSV")
    sp.add_argument("--format", choices=("csv",), default="csv")
    sp = sub.add_parser(
        "add",
        help="append an entry",
        usage="pennywise add [-h] FILE DATE CATEGORY AMOUNT [NOTE]",
        allow_abbrev=False,
    )
    sp.add_argument("args", nargs="*", metavar="FILE DATE CATEGORY AMOUNT [NOTE]")
    return p


def _normalize(argv):
    """Let values that start with a dash be values, not unknown options."""
    argv = list(argv)
    if argv[:1] == ["add"]:
        if argv[1:2] in (["-h"], ["--help"]):
            return argv
        return ["add", "--"] + argv[1:]
    out = []
    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok == "--":
            out.extend(argv[i:])
            break
        nxt = argv[i + 1] if i + 1 < len(argv) else None
        if (tok in _VALUE_OPTS and nxt is not None and nxt.startswith("-")
                and nxt not in _KNOWN_FLAGS and nxt not in ("-", "--")):
            out.append(tok + "=" + nxt)
            i += 2
            continue
        out.append(tok)
        i += 1
    return out


def _read_ledger(path):
    label = "<stdin>" if path == "-" else path
    try:
        if path == "-":
            stream = sys.stdin
            data = stream.buffer.read() if hasattr(stream, "buffer") else stream.read()
        else:
            with open(path, "rb") as fh:
                data = fh.read()
    except OSError as exc:
        raise _Exit(2, "cannot read %s: %s" % (label, exc.strerror or exc)) from None
    if isinstance(data, bytes):
        try:
            text = data.decode("utf-8-sig")
        except UnicodeDecodeError as exc:
            line = len(re.findall(rb"\r\n|\n|\r", data[: exc.start])) + 1
            raise _Exit(1, "%s: line %d: invalid UTF-8" % (label, line)) from None
    else:
        text = data
    try:
        return ledger.parse(text)
    except ParseError as exc:
        raise _Exit(1, "%s: %s" % (label, exc)) from None


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)


def _lines(lines):
    return "".join(line + "\n" for line in lines)


def _json(obj):
    return json.dumps(obj) + "\n"


def _cmd_balance(args):
    total = money(ledger.balance(_read_ledger(args.file)))
    return _json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _read_ledger(args.file)
    groups = (ledger.by_month if args.by == "month" else ledger.by_category)(entries)
    names = sorted(groups)
    if args.json:
        return _json({n: money(groups[n]) for n in names})
    return _lines("%s  %s" % (n, money(groups[n])) for n in names)


def _cmd_list(args):
    entries = ledger.filter_entries(
        _read_ledger(args.file), args.category, args.since, args.until)
    entries = _sorted(entries)
    if args.json:
        return _json([
            {"date": e.date.isoformat(), "category": e.category,
             "amount": money(e.amount), "note": e.note}
            for e in entries])
    return _lines(entry_line(e) for e in entries)


def _cmd_export(args):
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted(_read_ledger(args.file)):
        writer.writerow([e.date.isoformat(), e.category, money(e.amount), e.note])
    return buf.getvalue()


def _cmd_add(args):
    if len(args.args) not in (4, 5):
        raise _Exit(2, "usage: pennywise add FILE DATE CATEGORY AMOUNT [NOTE]")
    path, date, category, amount = args.args[:4]
    note = args.args[4] if len(args.args) == 5 else ""
    for name, value in (("date", date), ("category", category), ("amount", amount)):
        if not value or any(ch.isspace() for ch in value):
            raise _Exit(1, "line 1: invalid %s %r" % (name, value))
    if "\n" in note or "\r" in note:
        raise _Exit(1, "line 1: note must not contain a line break")
    try:
        for value in (date, category, amount, note):
            value.encode("utf-8")
    except UnicodeEncodeError:
        raise _Exit(1, "line 1: entry is not valid UTF-8 text") from None
    try:
        entry = ledger.parse("%s %s %s %s" % (date, category, amount, note))[0]
    except ParseError as exc:
        raise _Exit(1, str(exc)) from None
    line = entry_line(entry)
    try:
        with open(path, "a+b") as fh:
            fh.seek(0, os.SEEK_END)
            prefix = b""
            if fh.tell() > 0:
                fh.seek(-1, os.SEEK_END)
                if fh.read(1) not in (b"\n", b"\r"):
                    prefix = b"\n"
            fh.seek(0, os.SEEK_END)
            fh.write(prefix + line.encode("utf-8") + b"\n")
    except OSError as exc:
        raise _Exit(2, "cannot write %s: %s" % (path, exc.strerror or exc)) from None
    return line + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
    "add": _cmd_add,
}


def _write_out(text):
    out = sys.stdout
    if not text:
        return
    if hasattr(out, "buffer"):
        out.flush()
        out.buffer.write(text.encode("utf-8"))
        out.buffer.flush()
    else:
        out.write(text)
        out.flush()


def main(argv=None):
    """Run the command line; returns the exit status."""
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        args = _build_parser().parse_args(_normalize(argv))
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        text = _COMMANDS[args.command](args)
    except _Exit as exc:
        print("pennywise: %s" % exc.message, file=sys.stderr)
        return exc.code
    try:
        _write_out(text)
    except BrokenPipeError:
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError, AttributeError):
            pass
        return 1
    except OSError as exc:
        print("pennywise: cannot write output: %s" % (exc.strerror or exc), file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
