"""Ledger parsing and reporting (library API)."""

import datetime
import re
from dataclasses import dataclass
from decimal import MAX_EMAX, MIN_EMIN, Context, Decimal

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]{1,2})?")
_LINE_RE = re.compile(r"[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(.*)", re.DOTALL)
_NEWLINE_RE = re.compile(r"\r\n|\n|\r")


class ParseError(ValueError):
    """A mistake in the ledger; ``line`` is the 1-based line number."""

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text):
    """Strict YYYY-MM-DD -> date; ValueError when malformed or not a real day."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (want YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def _parse_line(line, number):
    m = _LINE_RE.fullmatch(line)
    if not m:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_s, category, amount_s, rest = m.groups()
    try:
        date = parse_date(date_s)
    except ValueError as exc:
        raise ParseError(number, str(exc)) from None
    if any(ch.isspace() for ch in category):
        raise ParseError(number, "invalid category %r" % category)
    if not _AMOUNT_RE.fullmatch(amount_s):
        raise ParseError(number, "invalid amount %r" % amount_s)
    return Entry(date, category.lower(), Decimal(amount_s), rest.strip())


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    if text.startswith("\ufeff"):
        text = text[1:]
    entries = []
    for number, line in enumerate(_NEWLINE_RE.split(text), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        entries.append(_parse_line(line, number))
    return entries


def _total(amounts):
    amounts = list(amounts)
    digits = max((len(a.as_tuple().digits) for a in amounts), default=1)
    ctx = Context(prec=digits + len(str(len(amounts))) + 4, Emax=MAX_EMAX, Emin=MIN_EMIN)
    total = Decimal(0)
    for a in amounts:
        total = ctx.add(total, a)
    return total


def balance(entries):
    """Exact total of all amounts (Decimal 0 for none)."""
    return _total(e.amount for e in entries)


def _group(entries, keyfunc):
    groups = {}
    for e in entries:
        groups.setdefault(keyfunc(e), []).append(e.amount)
    return {k: _total(v) for k, v in groups.items()}


def by_category(entries):
    return _group(entries, lambda e: e.category)


def by_month(entries):
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    """Matching entries in the order given; None means no filter on that field."""
    if category is not None:
        category = category.lower()
    out = []
    for e in entries:
        if category is not None and e.category != category:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        out.append(e)
    return out
